VALUES 
('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b1', 'Винодельня «Кубань-Вино»', 'winery', 'Крупнейшая винодельня в регионе с уникальными подвалами. Отличные экскурсии и профессиональные сомелье расскажут всё об этапе создания вина.', 'Дегустации и экскурсии на Таманском полуострове.', 45.2117, 36.7144, 'Темрюкский район', 'Тамань', ARRAY['wine', 'tasting', 'couples'], 500, 1500, 4.8),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b2', 'Фермерское хозяйство «Баракат»', 'farm', 'Отличное место для семейного отдыха. Вы сможете покормить животных, попробовать настоящий домашний сыр из козьего молока.', 'Домашний козий сыр и уютная ферма.', 45.1962, 36.8301, 'Темрюк', 'Тамань', ARRAY['farming', 'family', 'cheese'], 300, 800, 4.9),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b3', 'Грязевой вулкан Тиздар', 'nature', 'Уникальный природный вулкан с целебной грязью. Находится в нескольких десятках метров от Азовского моря. Купание абсолютно безопасно.', 'Купание в целебном грязевом кратере.', 45.1234, 36.8012, 'поселок За Родину', 'Азов', ARRAY['nature', 'healing', 'family'], 700, 700, 4.5),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b4', 'Этнокомплекс «Атамань»', 'festival', 'Огромный музей казачьего быта под открытым небом. Здесь регулярно проходят гастрономические фестивали и ярмарки ремесленников.', 'Казачья станица и самый вкусный борщ.', 45.2301, 36.6112, 'Тамань', 'Тамань', ARRAY['history', 'culture', 'gastronomy'], 400, 400, 4.7),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b5', 'Виноградники Фанагория', 'winery', 'Легендарные виноградники с потрясающими живописными видами. Можно пройтись по аллеям роз и спуститься в хранилище.', 'Фанагорийские вина и красивые поля.', 45.1900, 36.5800, 'Сенной', 'Тамань', ARRAY['wine', 'views', 'premium'], 600, 2000, 4.9),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b6', 'Лавандовое поле Прованс Кубани', 'nature', 'Невероятные поля цветущей лаванды. Отличное место для фотосессий на закате. Рядом продают классное лавандовое мороженое.', 'Атмосферные лавандовые поля в горах.', 44.8812, 38.0233, 'Северская', 'Горы', ARRAY['nature', 'photo', 'couples'], 200, 200, 4.8),

('fcb8b8b8-b8b8-b8b8-b8b8-b8b8b8b8b8b7', 'Долина Лефкадия', 'winery', 'Настоящая российская Тоскана в Крымском районе. Огромная территория, рестораны премиум-класса, собственные сыроварни и премиальные вина.', 'Прекрасное вино и французские сыры.', 44.9383, 37.8687, 'Крымский район', 'Крымск', ARRAY['wine', 'premium', 'gastronomy', 'photo'], 1000, 5000, 5.0)
